const e = $('Eingang prüfen').first().json;
const n = $('Neu entscheiden').first().json;
const zeilen = $input.all().map((i) => i.json).filter((r) => r && r.schluessel === n.schluessel);
const s = sperreEntscheid(zeilen, e.lauf_id, e.lauf_start);
let schritt = 'nichts', grund = s.grund, erledigt = null;
if (s.weiter) schritt = 'senden';
else if (s.erledigt && s.erledigt.aktion === 'versendet') { schritt = 'nachziehen'; grund = 'schon versendet – nachgezogen'; erledigt = s.erledigt; }
else if (s.tot) { schritt = 'suchen'; grund = 'Reservierung eines abgebrochenen Laufs (Lauf ' + s.tot.lauf_id + ') – im Gesendet-Ordner suchen'; }
return [{ json: { schritt, grund, erledigt, tot: s.tot || null, zeilen: zeilen.length,
  such_q: s.tot ? gesendetSuche(e.vorgang, s.tot.zeit_utc) : '' } }];

