}

function vsKopf(headers, name) {
  var h = (headers || []).filter(function (x) { return String(x.name).toLowerCase() === name.toLowerCase(); })[0];
  return h ? String(h.value) : '';
}

function nachpruefung(antwort, empfaenger) {
