    nachpruefung, handVersandAuswerten, zellenNachVersand };
}

// ==== Treiber, nicht Teil des Kerns (bau/werkzeuge/zz_bau_b678.py) ====
const lief = (x) => { const v = $(x).isExecuted; if (typeof v !== 'boolean') throw new Error('isExecuted nicht verfuegbar'); return v; };

const e = $('Eingang prüfen').first().json;
const n = $('Neu entscheiden').first().json;
let datum, thread;
if (lief('Versendet eintragen')) { const v = $('Versendet prüfen').first().json.zeile; datum = v.datum; thread = v.thread_id; }
else if (lief('Gefunden eintragen')) { const v = $('Gesendet auswerten').first().json.zeile; datum = v.datum; thread = v.thread_id; }
else { const x = $('Sperre prüfen').first().json.erledigt; datum = x.datum; thread = x.thread_id || n.anlage.thread_id; }
const data = zellenNachVersand({ zeile: n.anlage.zeile, aktion: e.aktion, datum, thread_id: thread }, n.werte.anlagen[0] || []);
return [{ json: { url: e.url_zellen, body: { valueInputOption: 'RAW', data } } }];

const lief = (x) => { const v = $(x).isExecuted; if (typeof v !== 'boolean') throw new Error('isExecuted nicht verfuegbar'); return v; };

const e = $('Eingang prüfen').first().json;
const n = $('Neu entscheiden').first().json;
const aus = { typ: 'versand', anlagen_id: e.anlagen_id, aktion: e.aktion, vorgang: e.vorgang, ergebnis: 'nicht versendet', grund: n.grund,
  gmail_id: '', thread_id: '', an_ist_testempfaenger: null, nachpruefung: null, zellen: null, mit_referenz: null };
if (lief('Mail bauen')) {
  const m = $('Mail bauen').first().json;
  aus.an_ist_testempfaenger = m.an_ist_testempfaenger === undefined ? null : m.an_ist_testempfaenger;
  aus.mit_referenz = !!m.referenz;
  if (!m.ok) aus.grund = m.grund;
}
if (lief('Sperre prüfen')) {
  const s = $('Sperre prüfen').first().json;
  aus.grund = s.grund;
  if (s.schritt === 'nachziehen') { aus.ergebnis = 'schon versendet'; aus.gmail_id = s.erledigt.gmail_id; aus.thread_id = s.erledigt.thread_id || ''; }
  if (s.schritt === 'suchen') {
    const g = lief('Gesendet auswerten') ? $('Gesendet auswerten').first().json : { gefunden: false };
    if (g.gefunden) { aus.ergebnis = 'nachgezogen'; aus.grund = 'im Gesendet-Ordner gefunden – nachgezogen'; aus.gmail_id = g.zeile.gmail_id; aus.thread_id = g.zeile.thread_id; }
    else { aus.ergebnis = 'versand_unklar'; aus.grund = 'Reservierung eines abgebrochenen Laufs (Lauf ' + s.tot.lauf_id + ') ohne Versandbestätigung, im Gesendet-Ordner nicht gefunden – nicht erneut gesendet; bitte prüfen und in „Versandstatus klären“ versendet oder nicht versendet eintragen'; }
  }
}
if (lief('Versendet prüfen')) {
  const v = $('Versendet prüfen').first().json;
  if (v.ok) { aus.ergebnis = 'versendet'; aus.grund = ''; aus.gmail_id = v.zeile.gmail_id; aus.thread_id = v.zeile.thread_id; aus.nachpruefung = v.np; }
  else { aus.ergebnis = 'versand_unklar'; aus.grund = v.grund + ' – nicht erneut gesendet'; }
}
if (lief('Zellen schreiben')) {
  const z = $('Zellen schreiben').first().json;
  if (z.statusCode !== 200) throw new Error('Versand - Zellen nach dem Versand nicht geschrieben, HTTP ' + z.statusCode + ' - ' + e.anlagen_id);
  aus.zellen = z.body && z.body.totalUpdatedCells;
}
return [{ json: aus }];
